import { Controller, Patch, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 제목 최대 길이는 스키마(VARCHAR(500))와 같다.
const MAX_TITLE_LENGTH = 500;
// 가정: 지원하는 그림 형식 목록 (스펙에 허용 형식이 없어 일반적인 웹 이미지 형식으로 정함).
const SUPPORTED_IMAGE_TYPES = ['png', 'jpg', 'jpeg', 'gif', 'bmp'];
// 가정: 작성 중(임시 저장) 상태인 '기안' 문서만 수정할 수 있다.
const EDITABLE_STATUS = '기안';

// 본문 HTML 안의 그림이 지원하지 않는 형식인지 확인한다.
function hasUnsupportedImage(body: string): boolean {
  const tags = body.match(/<img[^>]*>/gi) ?? [];
  for (const tag of tags) {
    const found = /src *= *["']([^"']*)["']/i.exec(tag);
    if (!found) {
      continue;
    }
    const src = found[1];
    const dataUri = /^data:image[/]([a-z0-9.+-]+)/i.exec(src);
    if (dataUri) {
      if (!SUPPORTED_IMAGE_TYPES.includes(dataUri[1].toLowerCase())) {
        return true;
      }
      continue;
    }
    if (/^data:/i.test(src)) {
      return true;
    }
    const path = src.split('?')[0];
    const ext = /[.]([a-z0-9]+)$/i.exec(path);
    if (ext && !SUPPORTED_IMAGE_TYPES.includes(ext[1].toLowerCase())) {
      return true;
    }
  }
  return false;
}

@Controller('api/v1')
export class FnSfr029201Xbf1c37Controller {
  @Patch('/approval-documents/:approvalDocumentId')
  async updateApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['approvalDocumentId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    const rawTitle = data['title'];
    const rawBody = data['body'];
    let title: string | null = null;
    let body: string | null = null;
    if (rawTitle !== undefined && rawTitle !== null) {
      if (typeof rawTitle !== 'string' || rawTitle.trim() === '') {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목을 입력해 주세요.');
      }
      if (rawTitle.length > MAX_TITLE_LENGTH) {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목은 500자 이하로 입력해 주세요.');
      }
      title = rawTitle;
    }
    if (rawBody !== undefined && rawBody !== null) {
      if (typeof rawBody !== 'string') {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 본문 형식이 올바르지 않습니다.');
      }
      body = rawBody;
    }
    if (title === null && body === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수정할 제목 또는 본문을 입력해 주세요.');
    }
    if (body !== null && hasUnsupportedImage(body)) {
      throw new ApiError(422, 'UNSUPPORTED_OBJECT_FORMAT', '지원하지 않는 형식의 그림 또는 객체가 포함되어 있어 삽입할 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      if (found[0]['approvalStatus'] !== EDITABLE_STATUS) {
        throw new ApiError(409, 'INVALID_STATE', '작성 중인 문서만 수정할 수 있습니다.');
      }
      const rows = await db.query(
        'UPDATE approval_document SET title = COALESCE(CAST(:title AS varchar), title), body = COALESCE(CAST(:body AS text), body), updated_at = now() WHERE approval_document_id = CAST(:id AS bigint) RETURNING approval_document_id AS "approvalDocumentId", title AS "title", body AS "body"',
        { id: idText, title, body },
      );
      return rows[0];
    });
  }
}

