import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr029201Xbf1c37Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 작성·수정한 문서를 목록으로 보인다.
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [viewing, setViewing] = useState<Row | null>(null);

  const [formId, setFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [businessType, setBusinessType] = useState('');
  const [businessId, setBusinessId] = useState('');
  const [urgent, setUrgent] = useState('false');
  const [secret, setSecret] = useState('false');

  const draftCount = rows.filter((r) => r['approvalStatus'] === '기안').length;

  function openCreate() {
    setFormId('');
    setTitle('');
    setBody('');
    setBusinessType('');
    setBusinessId('');
    setUrgent('false');
    setSecret('false');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setTitle(String(row['title'] ?? ''));
    setBody(String(row['body'] ?? ''));
    setEditing(row);
  }

  async function submitCreate() {
    if (formId === '') {
      throw new Error('결재양식을 선택해 주세요.');
    }
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력해 주세요.');
    }
    if (businessType.trim() === '') {
      throw new Error('연계 업무 유형을 입력해 주세요.');
    }
    if (businessId.trim() === '' || Number.isNaN(Number(businessId))) {
      throw new Error('연계 업무 식별자를 숫자로 입력해 주세요.');
    }
    const result = await call('POST', '/approval-documents', role, {
      approvalFormId: formId,
      title,
      body,
      linkedBusinessType: businessType,
      linkedBusinessId: Number(businessId),
      isUrgent: urgent === 'true',
      isSecret: secret === 'true',
    });
    const created: Row = {
      approvalDocumentId: result['approvalDocumentId'],
      approvalFormId: formId,
      documentNumber: result['documentNumber'],
      approvalStatus: result['approvalStatus'],
      title,
      body,
    };
    setRows([created, ...rows]);
    setCreating(false);
    notify('결재문서를 작성했습니다.');
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력해 주세요.');
    }
    const id = String(editing['approvalDocumentId']);
    const result = await call('PATCH', '/approval-documents/' + id, role, { title, body });
    setRows(
      rows.map((r) =>
        String(r['approvalDocumentId']) === id
          ? { ...r, title: result['title'], body: result['body'] }
          : r,
      ),
    );
    setEditing(null);
    notify('결재문서를 수정했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>작성한 문서</h2>
        <Tiles items={[['건수', rows.length]]} />
      </section>
      <section className="box span-4">
        <h2>작성 중</h2>
        <Tiles items={[['건수', draftCount]]} />
      </section>
      <section className="box span-12">
        <h2>결재문서</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openCreate}>문서 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="작성한 문서가 없습니다."
          onRowClick={(row) => setViewing(row)}
          columns={[
            { key: 'approvalDocumentId', label: '결재문서 ID' },
            {
              key: 'approvalFormId',
              label: '결재양식',
              render: (r) => <RefName table="approval_form" role={role} value={r['approvalFormId']} />,
            },
            { key: 'title', label: '문서 제목' },
            {
              key: 'approvalStatus',
              label: '결재 진행 상태',
              render: (r) => <Badge value={r['approvalStatus']} />,
            },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                r['approvalStatus'] === '기안' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      openEdit(r);
                    }}
                  >
                    수정
                  </button>
                ) : null,
            },
          ]}
        />
      </section>

      {creating && (
        <Drawer title="결재문서 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="작성">
            <Field label="결재양식" required>
              <LookupSelect table="approval_form" role={role} value={formId} onChange={setFormId} />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide hint="표·그림·객체는 선택 입력입니다. 특수문자도 그대로 저장됩니다.">
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="연계 업무 유형" required>
              <TextInput value={businessType} onChange={setBusinessType} />
            </Field>
            <Field label="연계 업무 식별자" required>
              <TextInput value={businessId} onChange={setBusinessId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select
                value={urgent}
                onChange={setUrgent}
                options={[['false', '아니오'], ['true', '예']]}
              />
            </Field>
            <Field label="보안문서 여부">
              <Select
                value={secret}
                onChange={setSecret}
                options={[['false', '아니오'], ['true', '예']]}
              />
            </Field>
          </Form>
        </Drawer>
      )}

      {editing && (
        <Drawer title="결재문서 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="저장">
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide hint="표·그림·객체를 넣을 수 있으며 지원하지 않는 형식은 거부됩니다.">
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
          </Form>
        </Drawer>
      )}

      {viewing && (
        <Drawer title="결재문서 상세" onClose={() => setViewing(null)}>
          <Pairs
            items={[
              ['결재문서 ID', String(viewing['approvalDocumentId'] ?? '')],
              ['결재양식', <RefName table="approval_form" role={role} value={viewing['approvalFormId']} />],
              ['문서번호', String(viewing['documentNumber'] ?? '')],
              ['결재 진행 상태', <Badge value={viewing['approvalStatus']} />],
              ['문서 제목', String(viewing['title'] ?? '')],
              ['문서 본문', String(viewing['body'] ?? '')],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
